function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json','X-Roundtable-Token':state.token,...opts.headers}});const data=await r.json();if(!r.ok){const error=new Error(data.message||data.error||r.statusText);error.issue=data.issue||null;throw error}return data}
function capture(){captureNewInputs();const fields={question:'#question',evidence:'#evidence',answerLang:'#answer-lang',topic:'#topic',depth:'#depth'};for(const [k,selector] of Object.entries(fields)){const el=$(selector);if(el)state[k]=el.value}const ub=$('#use-brief');if(ub)state.useBrief=ub.checked;for(const k of decisionKeys){const el=$('#decision-'+k);if(el)state.decision[k]=el.value}if(state.followup){for(const k of ['question','evidence','depth']){const el=$('#followup-'+k);if(el)state.followup[k]=el.value}for(const k of decisionKeys){const el=$('#followup-'+k);if(el)state.followup.decision[k]=el.value}}if(state.showManual){state.manualDraft={providerName:$('#manual-provider')?.value||'',model:$('#manual-model')?.value||'',text:$('#manual-text')?.value||'',sourceUrl:$('#manual-url')?.value||''}}}
function render(){const focus=document.activeElement?.id,selection=document.activeElement?.selectionStart;document.documentElement.lang=state.lang==='zh'?'zh-Hant':'en';document.title=state.lang==='zh'?'Roundtable · 研究與決策':'Roundtable · Research & decisions';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg width="29" height="29" viewBox="0 0 32 32" fill="none" aria-hidden="true"><circle cx="16" cy="16" r="9" stroke="currentColor" stroke-width="1.5"/><circle cx="16" cy="6" r="3" fill="currentColor"/><circle cx="7" cy="21" r="3" fill="currentColor"/><circle cx="25" cy="21" r="3" fill="currentColor"/></svg>Roundtable</div><div class="brand-note">Research & decisions</div><nav class="nav" aria-label="${t('workspace')}">${['lab','evaluations','history','settings'].map(p=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}">${icon(p)}${t(p)}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-badge"><span></span>${t('local')}</div><div>${t('localNote')}</div><div class="version">PERSONAL WORKSPACE · v0.6.0</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${t('workspace')} <span style="margin:0 10px;color:#abb6c7">/</span> <strong>${t(state.page)}</strong></div><div class="top-actions"><div class="lang-toggle" aria-label="Interface language"><button data-lang="zh" class="${state.lang==='zh'?'active':''}">繁中</button><button data-lang="en" class="${state.lang==='en'?'active':''}">EN</button></div><span class="avatar">JR</span></div></header><div class="workspace">${globalIssueView()}${state.page==='lab'?lab():state.page==='evaluations'?evaluationView():state.page==='history'?historyView():settingsView()}</div></main></div>`;bind();if(focus){const field=document.getElementById(focus);if(field&&!field.disabled){field.focus({preventScroll:true});if(typeof selection==='number')try{field.setSelectionRange(selection,selection)}catch{}}}}
function briefView(){const b=state.brief;return `<section class="panel"><div class="panel-body"><div class="brief-label"><span class="pill blue">${t('prepared')}</span><span class="footnote">${t('notDebate')}</span></div><h2 style="font-size:22px;margin:8px 0 12px">${t('futureTitle')}</h2><p class="brief-intro">${t('futureIntro')}</p>${b?`<div class="timeline">${b.horizons.map((h,i)=>`<button class="horizon ${state.horizon===i?'selected':''}" data-horizon="${i}" aria-pressed="${state.horizon===i}"><small>+${h.years} ${t('years')}</small><strong>${h.year}</strong><span>${h.years<=20?t('conditional'):t('scenario')}</span></button>`).join('')}</div>${horizonView(b.horizons[state.horizon])}<div class="takeaways"><h3 style="font-size:15px">${t('decisions')}</h3><ul>${(b.decisionTakeaways||[]).map(x=>`<li>${esc(typeof x==='string'?x:val(x,'body')||val(x,'text')||val(x,'recommendation'))}</li>`).join('')}</ul></div>${b.historicalLessons?.length?`<h3 style="margin-top:26px">${t('historyLesson')}</h3>${b.historicalLessons.map(x=>`<div class="history-lesson"><h3>${esc(val(x,'title'))}</h3><p>${esc(val(x,'body')||val(x,'lesson')||val(x,'text'))}</p></div>`).join('')}`:''}<div class="divider"></div><p class="footnote">${t('asOf')} ${esc(b.asOf||'2026-09-20')} · ${t('briefOnly')}</p>`:`<div class="timeline">${[10,20,30,40,50].map(y=>`<div class="horizon"><small>+${y} ${t('years')}</small><strong>${2026+y}</strong><span>${y<=20?t('conditional'):t('scenario')}</span></div>`).join('')}</div><div class="notice">${t('briefLoading')}</div>`}</div></section>`}
function horizonView(h){return `<div class="horizon-detail"><span class="eyebrow">${h.year} · ${h.years<=20?t('conditional'):t('scenario')}</span><h3 style="font-size:20px;margin:9px 0 13px">${esc(val(h,'theme'))}</h3><p>${esc(val(h,'rationale'))}</p><div class="uncertainty"><strong>${t('uncertainty')}</strong><br>${esc(val(h,'uncertainty'))}</div><div class="source-chips">${(h.sourceIds||[]).map(id=>{const s=state.brief.sources.find(s=>s.id===id);return s?`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(id)} ↗</a>`:''}).join('')}</div></div>`}
function sourceType(type){const names={historical_research_working_paper:['歷史研究工作論文','History working paper'],peer_reviewed_economics_research:['同儕審查經濟研究','Peer-reviewed economics'],primary_historical_court_record:['法院原始紀錄','Court record'],primary_historical_product_announcement:['產品發布原始紀錄','Product announcement'],research_institute_evidence_synthesis:['年度研究報告','Annual research report'],intergovernmental_analysis_and_projection:['跨政府組織分析','Intergovernmental analysis'],industry_federation_statistics:['產業統計','Industry statistics'],research_funder_report_of_primary_clinical_study:['臨床研究資助單位報告','Clinical study funder report'],peer_reviewed_experimental_research:['同儕審查實驗研究','Peer-reviewed experiment'],government_research_roadmap:['政府研究路線圖','Government research roadmap']};return names[type]?.[state.lang==='zh'?0:1]||type.replaceAll('_',' ')}
function sessionCitations(){const links=new Map();for(const m of (state.session?.messages||[]).filter(m=>!m.stale)){for(const match of m.text.matchAll(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g)){const url=safeUrl(match[2]);if(url==='#')continue;const item=links.get(url)||{url,title:match[1],providers:new Set()};item.providers.add(m.providerName||m.provider);links.set(url,item)}}return [...links.values()]}
function markdown(text){
 const inline=value=>esc(value).replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>`<a href="${esc(safeUrl(url.replace(/&amp;/g,'&')))}" target="_blank" rel="noopener noreferrer">${label}</a>`).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
 const lines=String(text).split('\n'),out=[],cells=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());let i=0;
 while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue}if(line.startsWith('```')){const code=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))code.push(lines[i++]);i++;out.push(`<pre><code>${esc(code.join('\n'))}</code></pre>`);continue}
 if(i+1<lines.length&&line.includes('|')&&/^\s*\|?\s*:?-+:?\s*\|[\s|:\-]+$/.test(lines[i+1])){const head=cells(line);i+=2;const rows=[];while(i<lines.length&&lines[i].includes('|')&&lines[i].trim())rows.push(cells(lines[i++]));out.push(`<div class="table-scroll"><table><thead><tr>${head.map(c=>`<th>${inline(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${head.map((_,n)=>`<td>${inline(row[n]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue}
 const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){out.push(`<h3>${inline(heading[2])}</h3>`);i++;continue}
 if(/^\s*([-*]|\d+\.)\s+/.test(line)){const ordered=/^\s*\d+\./.test(line),tag=ordered?'ol':'ul',items=[];while(i<lines.length&&/^\s*([-*]|\d+\.)\s+/.test(lines[i]))items.push(lines[i++].replace(/^\s*([-*]|\d+\.)\s+/,''));out.push(`<${tag}>${items.map(v=>`<li>${inline(v)}</li>`).join('')}</${tag}>`);continue}
 if(/^\s*---+\s*$/.test(line)){out.push('<hr>');i++;continue}out.push(`<p>${inline(line)}</p>`);i++}
 return out.join('');}
function discussionView(){const s=state.session;const final=s?.messages?.findLast(m=>m.stage==='synthesis'&&!m.stale);const displayed=final?[final,...s.messages.filter(m=>m!==final)]:s?.messages||[];return `<div class="section-title"><div><span class="subtle">${s?`${s.participants?.length||0} ${t('providerCount')} · ${t(s.status)}`:t('emptyDiscussion')}</span></div><div class="tab-actions"><button class="btn small" data-action="manual" ${state.running||state.starting?'disabled':''}>${icon('plus',14)}${t('manual')}</button>${s?.messages?.length?`<a class="btn small" href="/api/sessions/${esc(s.id)}/export" download style="text-decoration:none">${icon('download',14)}${t('export')}</a>`:`<button class="btn small" data-action="export">${icon('download',14)}${t('export')}</button>`}</div></div>${s?.messages?.length?`${s.mode==='single'?`<div class="notice amber" style="margin:0 0 14px">${t('singleNote')}</div>`:''}<section class="panel">${state.running?`<div class="progress-bar"><span style="width:${Math.min(95,(s.messages.length/(s.participants.length*2+1))*100)}%"></span></div>`:''}${displayed.map(m=>`<article class="message ${m.stage==='synthesis'&&!m.stale?'synthesis-message':''}"><div class="message-head">${symbol(m.provider)}<strong>${esc(m.providerName||m.provider)} · ${esc(m.model||(m.requestedModel?(state.lang==='zh'?'指定：':'Requested: ')+m.requestedModel:t('defaultModel')))}</strong><span class="pill ${m.stage==='synthesis'?'green':''}">${t(m.stage)||m.stage}</span>${m.stale?`<span class="pill amber">${t('stale')}</span>`:''}<time>${new Date(m.createdAt).toLocaleTimeString(state.lang==='zh'?'zh-TW':'en-US',{hour:'2-digit',minute:'2-digit'})}</time></div>${!m.model&&m.usageModels?.length?`<p class="footnote">${state.lang==='zh'?'主回答模型未確認；使用量紀錄包含：':'Main response model unconfirmed; usage records include: '}${esc(m.usageModels.join(', '))}</p>`:''}${m.manual?`<div class="notice amber" style="margin:0 0 12px">${t('manualProvenance')}${m.sourceUrl?` · <a href="${esc(safeUrl(m.sourceUrl))}" target="_blank" rel="noopener noreferrer">${t('readSource')}</a>`:''}</div>`:''}<details class="message-model-details"><summary>${t('modelRecord')}</summary><dl><dt>${t('requestedModel')}</dt><dd>${esc(m.requestedModel||t('defaultModel'))}</dd><dt>${t('requestedEffort')}</dt><dd>${esc(m.requestedReasoningEffort||t('defaultEffort'))}</dd><dt>${t('actualModel')}</dt><dd>${esc(m.model||t('notReported'))}</dd></dl><p class="footnote">${t('effortNote')}</p></details><div class="message-body">${markdown(responseText(m.text))}${responseText(m.text)!==m.text.trim()?`<details><summary>${t('showOriginal')}</summary><pre>${esc(m.text)}</pre></details>`:''}</div></article>`).join('')}${s.error||s.errorIssue?issueView(s.errorIssue,s.error):''}${state.running?`<div class="message"><span class="running-icon"></span> <span class="subtle">${esc(s.currentProvider||'')} · ${t(s.currentStage||'pending')}…</span></div>`:''}</section>`:`<section class="panel"><div class="empty"><div class="empty-icon">${icon('chat',25)}</div><h3>${t('emptyDiscussion')}</h3><p>${t('emptyDiscussionText')}</p><button class="btn small" data-action="manual" ${state.running||state.starting?'disabled':''}>${t('manual')}</button></div>${s?.error||s?.errorIssue?issueView(s.errorIssue,s.error):''}${state.running?`<div class="message"><span class="running-icon"></span> ${t('running')} · ${esc(s?.currentProvider||'')}</div>`:''}</section>`}${s?.messages?.some(m=>m.manual)&&!state.running?`<button class="btn primary" data-action="synthesize">${t('synthesize')}</button>`:''}<section class="panel ${state.showManual?'':'hidden'}" id="manual-panel"><div class="panel-head"><h2>${t('importTitle')}</h2><button class="text-link" data-action="manual-close">×</button></div><div class="panel-body"><div class="form-row"><label>${t('provider')}<input type="text" id="manual-provider" placeholder="Gemini / …"></label><label>${t('model')}<input type="text" id="manual-model" placeholder="${t('model')}"></label></div><label class="field-label" for="manual-text">${t('response')}</label><textarea class="standard" id="manual-text"></textarea><label class="field-label" for="manual-url" style="margin-top:12px">${t('sourceUrl')}</label><input type="url" id="manual-url" style="width:100%"><div class="notice amber">${t('manualProvenance')}</div><div class="manual-tools"><button class="btn primary" data-action="import">${t('import')}</button><button class="btn" data-action="copy">${t('copyPrompt')}</button></div><p class="footnote">${t('useImport')}</p></div></section>`}
function historyView(){const rows=state.showTrash?state.trash:state.sessions;return `<div class="title-row"><div><h1>${t('history')}</h1><p class="subtle">${t('historyNote')}</p></div><button class="btn" data-action="new">${icon('plus')}${t('new')}</button></div><div class="history-controls"><button class="btn ${!state.showTrash?'primary':''}" data-history-view="active">${t('history')} (${state.sessions.length})</button><button class="btn ${state.showTrash?'primary':''}" data-history-view="trash">${t('deletedSessions')} (${state.trash.length})</button></div>${state.showTrash?`<p class="footnote">${t('trashNote')}</p>`:''}${rows.length?rows.map(s=>`<article class="session-card"><button class="session-open" ${state.showTrash?'disabled':`data-session="${esc(s.id)}"`}>${icon('chat',26)}<span class="session-label"><strong>${esc(s.question)}</strong><small>${new Date(s.createdAt).toLocaleString(state.lang==='zh'?'zh-TW':'en-US')} · ${s.messageCount||0} ${state.lang==='zh'?'則發言':'responses'}</small></span></button><span class="pill ${s.status==='complete'?'green':''}">${t(s.status)}</span><button class="btn small ${state.showTrash?'':'danger'}" data-${state.showTrash?'restore-session':'delete-session'}="${esc(s.id)}" ${s.status==='running'&&!state.showTrash?'disabled':''} aria-label="${t(state.showTrash?'restoreSession':'deleteSession')}: ${esc(s.question)}">${t(state.showTrash?'restoreSession':'deleteSession')}</button></article>`).join(''):`<section class="panel empty"><h3>${t(state.showTrash?'trashEmpty':'noHistory')}</h3>${state.showTrash?'':`<p>${t('historyEmpty')}</p>`}</section>`}`}
async function deleteSession(id){const session=state.sessions.find(s=>s.id===id);if(!session||session.status==='running')return toast(t('activeDelete'));await api('/api/sessions/'+id,{method:'DELETE',body:'{}'});if(state.session?.id===id){clearTimeout(state.poll);Object.assign(state,{session:null,running:false,question:'',evidence:'',attachments:[],useBrief:false,showManual:false,depth:'standard',decision:emptyDecision(),followup:null,selected:defaultParticipants()})}if(localStorage.getItem('rt-last-session')===id)localStorage.removeItem('rt-last-session');await loadSessions();toast(t('deletedNotice'))}
async function restoreSession(id){await api('/api/trash/'+id+'/restore',{method:'POST',body:'{}'});await loadSessions();toast(t('restored'))}

function settingsView(){return `<div class="title-row"><div><h1>${t('settings')}</h1><p class="subtle">${t('settingsIntro')}</p></div><button class="btn" data-action="refresh">${t('refresh')}</button></div><section class="panel"><div class="panel-body"><h2>${t('firstUse')}</h2><p class="subtle">${t('setupNote')}</p></div></section><div class="settings-grid">${state.providers.map(p=>`<section class="panel settings-card">${symbol(p.id)}<h2>${esc(p.name)}</h2><p style="margin-top:7px"><span class="pill ${p.ready?'green':'amber'}">${p.ready?t('available'):p.installed?t('installed'):t('missing')}</span></p><p>${esc(p.version||'')}</p>${diagnosticView(p)}<label class="field-label" for="model-${esc(p.id)}">${t('modelId')}</label><input type="text" id="model-${esc(p.id)}" data-model-id="${esc(p.id)}" list="models-${esc(p.id)}" value="${esc(state.modelDraft[p.id]??p.model??'')}" placeholder="${t('defaultModel')}"><datalist id="models-${esc(p.id)}">${(modelSuggestions[p.id]||[]).map(m=>`<option value="${esc(m)}"></option>`).join('')}</datalist>${p.reasoningEffort?`<p class="footnote">${t('effort')}: ${esc(p.reasoningEffort)}</p>`:''}<p class="footnote">${t('modelHint')}</p><div class="probe-separator"><h3>${t('probeOptional')}</h3><button class="btn small" data-probe="${esc(p.id)}" ${!p.installed||state.running||state.starting||state.evalBusy||state.evaluation?.status==='running'?'disabled':''}>${t('probe')}</button></div><p class="footnote">${t('probeHint')}</p><a href="${esc(safeUrl(p.docs))}" target="_blank" rel="noopener noreferrer">${t('docs')} ↗</a></section>`).join('')}</div><div class="manual-tools"><button class="btn primary" data-action="save-models">${t('save')}</button><button class="btn" data-action="quality-models">${t('qualityPreset')}</button></div><p class="footnote">${t('qualityNote')}</p><section class="panel" style="margin-top:24px"><div class="panel-body"><h2>${t('manualPlatform')}</h2><p class="subtle" style="margin-top:10px">${t('manualPlatformText')}</p><button class="btn" data-action="manual" ${state.running||state.starting?'disabled':''}>${t('manual')}</button></div></section><p class="footnote">${t('readOnly')} · ${t('noExtra')}</p>`}
function bind(){const clicks=(selector,fn)=>document.querySelectorAll(selector).forEach(el=>el.onclick=()=>Promise.resolve(fn(el)).catch(showError));clicks('[data-history-view]',el=>{capture();state.showTrash=el.dataset.historyView==='trash';render()});clicks('[data-delete-session]',async el=>{el.disabled=true;try{await deleteSession(el.dataset.deleteSession)}finally{el.disabled=false}});clicks('[data-restore-session]',async el=>{el.disabled=true;try{await restoreSession(el.dataset.restoreSession)}finally{el.disabled=false}});clicks('[data-probe]',async el=>{if(state.running||state.starting||state.evalBusy||state.evaluation?.status==='running')return;el.disabled=true;el.textContent=t('probing');try{await api(`/api/providers/${el.dataset.probe}/probe`,{method:'POST',body:'{}'});if(!state.session&&state.providers.find(p=>p.id===el.dataset.probe)?.defaultSelected!==false)state.selected.add(el.dataset.probe);await loadProviders(true);toast(t('available'))}finally{el.disabled=false;el.textContent=t('probe')}});clicks('[data-page]',el=>{capture();state.page=el.dataset.page;render();if(state.page==='history')return loadSessions();if(state.page==='evaluations')return loadEvaluations();if(state.page==='settings')return loadDiagnostics()});clicks('[data-lang]',el=>{capture();state.lang=el.dataset.lang;localStorage.setItem('rt-lang',state.lang);render()});clicks('[data-tab]',el=>{capture();state.tab=el.dataset.tab;render()});clicks('[data-horizon]',el=>{capture();state.horizon=Number(el.dataset.horizon);render()});document.querySelectorAll('[data-provider]').forEach(el=>el.onchange=()=>{capture();el.checked?state.selected.add(el.dataset.provider):state.selected.delete(el.dataset.provider);render()});document.querySelectorAll('[data-followup-provider]').forEach(el=>el.onchange=()=>{capture();if(!state.followup)return;const selected=new Set(state.followup.participants);el.checked?selected.add(el.dataset.followupProvider):selected.delete(el.dataset.followupProvider);state.followup.participants=[...selected];render()});clicks('[data-action]',el=>action(el.dataset.action));clicks('[data-session]',el=>openSession(el.dataset.session));clicks('[data-remove-attachment]',el=>{capture();state.attachments.splice(Number(el.dataset.removeAttachment),1);render()});clicks('[data-check-source]',async el=>{if(state.running||!state.session)return;const id=state.session.id,sourceId=el.dataset.checkSource;if(state.checkingSources.has(sourceId))return;capture();state.checkingSources.add(sourceId);render();try{const result=await api(`/api/sessions/${id}/check-source`,{method:'POST',body:JSON.stringify({sourceId})});if(state.session?.id===id)state.session=result;toast(t('checkFinished'))}finally{state.checkingSources.delete(sourceId);render()}});if($('#file-input'))$('#file-input').onchange=async e=>{capture();for(const file of e.target.files){if(file.size>200000){toast(t('attachmentTooLarge'));continue}state.attachments.push({name:file.name,text:await file.text()})}render();toast(t('sourceImported'))};if($('#answer-lang'))$('#answer-lang').onchange=e=>{state.answerLang=e.target.value;localStorage.setItem('rt-answer-lang',state.answerLang)};if($('#depth'))$('#depth').onchange=()=>{capture();render()};if($('#question'))$('#question').oninput=e=>{state.question=e.target.value;markClarificationChanged()};if($('#evidence'))$('#evidence').oninput=e=>{state.evidence=e.target.value;markClarificationChanged()};if(state.showManual&&state.manualDraft){for(const [id,key] of [['manual-provider','providerName'],['manual-model','model'],['manual-text','text'],['manual-url','sourceUrl']])if($('#'+id))$('#'+id).value=state.manualDraft[key]||''}bindResearchDetails();bindNewFeatures();updateElapsed()}
async function action(name){capture();if(name.startsWith('clarify-'))return clarificationAction(name);if(name.startsWith('eval-'))return evaluationAction(name);if(name==='dismiss-issue'){state.lastIssue=null;render();return}if(name==='new'||name==='example'){if(state.running||state.starting)return toast(t('confirmNew'));clearTimeout(state.poll);localStorage.removeItem('rt-last-session');Object.assign(state,{question:name==='example'?initialQuestion:'',evidence:'',attachments:[],useBrief:name==='example',decision:emptyDecision(),depth:'standard',topic:name==='example'?'technology':'general',session:null,selected:defaultParticipants(),page:'lab',tab:'summary',followup:null,showManual:false,manualDraft:null,clarification:null});render();$('#question')?.focus()}else if(name==='attach')$('#file-input')?.click();else if(name==='manual'){state.page='lab';state.tab='discussion';state.showManual=true;render();$('#manual-panel')?.scrollIntoView({behavior:'smooth',block:'center'})}else if(name==='manual-close'){state.showManual=false;render()}else if(name==='copy'){const text=await buildPrompt();if(window.webkit?.messageHandlers?.roundtable)window.webkit.messageHandlers.roundtable.postMessage({action:'copy',text});else await navigator.clipboard.writeText(text);toast(t('copied'))}else if(name==='refresh'){await loadProviders(true);toast(t('updated'))}else if(name==='quality-models'){await api('/api/settings',{method:'PUT',body:JSON.stringify({models:{codex:'gpt-6-astra',claude:'opus',antigravity:'gemini-3.1-pro-high'}})});state.modelDraft={};state.diagnostics={};await loadProviders(false);if(state.page==='settings')await loadDiagnostics();if(!state.session)state.selected=defaultParticipants();render();toast(t('saved'))}else if(name==='save-models'){const models={};document.querySelectorAll('[data-model-id]').forEach(el=>models[el.dataset.modelId]=el.value.trim());await api('/api/settings',{method:'PUT',body:JSON.stringify({models})});state.modelDraft={};state.diagnostics={};await loadProviders(false);if(state.page==='settings')await loadDiagnostics();toast(t('saved'))}else if(name==='start'||name==='resume'){if(state.starting||state.running)return;if(!state.question.trim())return toast(t('newQuestion'));const participants=state.session?.participants||[...state.selected].filter(id=>state.providers.some(p=>p.id===id&&p.ready));if(!participants.length)return toast(t('noProviders'));if(state.session&&!['queued','failed','paused'].includes(state.session.status))return;if(!state.session&&!await ensureClarification(participants))return;state.starting=true;render();try{if(!state.session){state.session=await api('/api/sessions',{method:'POST',body:JSON.stringify(requestData(participants,true))});localStorage.setItem('rt-last-session',state.session.id)}const result=await api(`/api/sessions/${state.session.id}/run`,{method:'POST',body:JSON.stringify({single:state.session.mode==='single'||participants.length===1})});adoptSession(result,false);await loadSessions(false);poll()}finally{state.starting=false;render()}}else if(name==='cancel'&&state.session){state.session=await api(`/api/sessions/${state.session.id}/cancel`,{method:'POST',body:'{}'});state.running=state.session.status==='running';await loadSessions(false);render()}else if(name==='export'){if(!state.session?.messages?.length)return toast(t('noResult'));const r=await fetch(`/api/sessions/${state.session.id}/export`);if(!r.ok)throw new Error(bi('無法匯出會議','Unable to export session'));download(await r.blob(),`roundtable-${state.session.id.slice(0,8)}.md`)}else if(name==='import'){if(state.running||state.starting)return;const providerName=$('#manual-provider').value.trim(),model=$('#manual-model').value.trim(),text=$('#manual-text').value.trim(),sourceUrl=$('#manual-url').value.trim();if(!providerName||!text)return toast(t('invalidImport'));if(!state.question.trim())return toast(t('newQuestion'));state.starting=true;try{if(!state.session)state.session=await api('/api/sessions',{method:'POST',body:JSON.stringify(payload([]))});state.session=await api(`/api/sessions/${state.session.id}/import`,{method:'POST',body:JSON.stringify({providerName,model,text,sourceUrl})});localStorage.setItem('rt-last-session',state.session.id);state.showManual=false;state.manualDraft=null;await loadSessions(false)}finally{state.starting=false;render()}}else if(name==='review-synthesis'){state.reviewSynthesis=!state.reviewSynthesis;render();$('#review-synthesis-preview')?.scrollIntoView({behavior:'smooth',block:'nearest'})}else if(name==='synthesize'){if(state.running||state.starting)return;const chair=synthesisChair();if(!chair)return toast(t('noProviders'));state.starting=true;try{const result=await api(`/api/sessions/${state.session.id}/synthesize`,{method:'POST',body:JSON.stringify({chair})});adoptSession(result,false);poll()}finally{state.starting=false;render()}}else if(name==='followup'){if(state.running||state.starting||!state.session)return;state.followup=state.followup||{question:'',evidence:'',decision:{...emptyDecision(),...state.session.decision},depth:state.session.depth||'standard',participants:[...defaultParticipants()]};render();$('#followup-panel')?.scrollIntoView({behavior:'smooth',block:'center'});$('#followup-question')?.focus()}else if(name==='followup-close'){state.followup=null;render()}else if(name==='create-followup'){if(state.running||state.starting||!state.session||!state.followup)return;if(!state.followup.question.trim())return toast(t('followupRequiresQuestion'));const participants=state.followup.participants.filter(id=>state.providers.some(p=>p.id===id&&p.ready));if(!participants.length)return toast(t('noProviders'));state.starting=true;const parent=state.session.id,body={...state.followup,participants,chair:participants.includes('codex')?'codex':participants[0]};render();try{const next=await api(`/api/sessions/${parent}/followup`,{method:'POST',body:JSON.stringify(body)});adoptSession(next);await loadSessions(false);toast(t('revisionReady'))}finally{state.starting=false;render()}}}
function payload(participants){return {question:state.question,topic:state.topic,answerLang:state.answerLang,evidence:state.evidence,attachments:state.attachments,useBrief:state.useBrief,depth:state.depth,decision:{...state.decision},participants,chair:participants[0]}}
async function buildPrompt(){const data=await api('/api/prompt',{method:'POST',body:JSON.stringify(payload([]))});return data.prompt}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function loadProviders(refresh=false){const r=await api('/api/providers'+(refresh?'?refresh=1':''));state.providers=r.providers;if(!state.providersLoaded){state.selected=defaultParticipants();state.providersLoaded=true}if(state.page!=='settings')capture();render()}
async function loadSessions(redraw=true){const [active,trash]=await Promise.all([api('/api/sessions'),api('/api/trash')]);state.sessions=active.sessions;state.trash=trash.sessions;if(redraw&&state.page==='history')render()}
async function openSession(id){if(state.starting)return;capture();const session=await api('/api/sessions/'+id);clearTimeout(state.poll);adoptSession(session);render();if(state.running)poll()}
function poll(){clearTimeout(state.poll);const id=state.session?.id;const update=async()=>{if(!id||state.session?.id!==id)return;try{const s=await api('/api/sessions/'+id);if(state.session?.id!==id)return;capture();const changed=state.session.updatedAt!==s.updatedAt||state.session.status!==s.status;state.session=s;state.running=s.status==='running';if(changed&&state.page==='lab'){const position=window.scrollY;render();window.scrollTo(0,position)}if(state.running)state.poll=setTimeout(update,1800);else await loadSessions(false)}catch(e){showError(e);if(state.session?.id===id)state.poll=setTimeout(update,5000)}};state.poll=setTimeout(update,900)}
async function init(){render();try{const boot=await api('/api/bootstrap');state.token=boot.token;state.brief=boot.brief;render();await Promise.all([loadProviders(),loadSessions(false)]);const last=localStorage.getItem('rt-last-session')||state.sessions[0]?.id,active=state.sessions.find(s=>s.status==='running');if(active||state.sessions.some(s=>s.id===last))await openSession(active?.id||last);else render();registerWebMCP()}catch(e){showError(e)}}
function registerWebMCP(){const mc=document.modelContext;if(!mc?.registerTool)return;const register=tool=>Promise.resolve(mc.registerTool(tool)).catch(()=>{});register({name:'read_roundtable_state',description:'Read the visible local research workspace and connection state. Does not call models.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({question:state.question,language:state.lang,tab:state.tab,providers:state.providers.map(p=>({id:p.id,ready:p.ready,model:p.model})),sessionId:state.session?.id,status:state.session?.status})});register({name:'stage_research_question',description:'Fill the question field without starting a model call or spending subscription quota.',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:12000}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.question!=='string'||!input.question.trim()||input.question.length>12000)throw new Error('Invalid question');if(state.running)throw new Error('Pause the active discussion first');state.question=input.question;state.page='lab';state.tab='summary';state.useBrief=false;state.session=null;state.decision=emptyDecision();state.depth='standard';state.evidence='';state.attachments=[];state.followup=null;state.selected=defaultParticipants();render();return {staged:true,question:state.question}}})}

const bi=(zh,en)=>state.lang==='zh'?zh:en;
const list=value=>Array.isArray(value)?value:[];
const plain=value=>typeof value==='string'?value:value==null?'':Array.isArray(value)?value.map(plain).join(' · '):typeof value==='object'?Object.entries(value).map(([k,v])=>`${k}: ${plain(v)}`).join(' · '):String(value);
const textList=value=>list(value).filter(x=>plain(x).trim()).map(x=>`<li>${esc(plain(x))}</li>`).join('');
const decisionKeys=['goal','options','constraints','timeframe'];
const emptyDecision=()=>Object.fromEntries(decisionKeys.map(k=>[k,'']));
const dateLabel=value=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString(state.lang==='zh'?'zh-TW':'en-US'):t('notReported');
const responseText=value=>String(value||'').replace(/```(?:roundtable-data|roundtable_data)\s*\n[\s\S]*?```/gi,'').trim();
const lastSynthesis=()=>list(state.session?.messages).findLast(m=>m.stage==='synthesis'&&!m.stale);
const analysis=()=>state.session?.analysis||{};
Object.assign(copy.zh,{summary:'決策摘要',evidence:'證據與來源',disputes:'分歧與待查',discussion:'完整討論',depth:'研究深度',overview:'快速概覽',standard:'標準研究',deep:'深入核查',goal:'想達成什麼？',options:'正在比較的選項',constraints:'限制與個人情況',timeframe:'決策時間範圍',goalHint:'例如：改善白天精神、選定研究方向',optionsHint:'例如：維持現狀、方案 A、方案 B',constraintsHint:'例如：時間、預算、既有經驗或適用對象',timeframeHint:'例如：未來 3 個月、畢業後 5 年',decisionContext:'你的決策背景',optionalContext:'以下可選填；不足的背景會保留為限制，不自行假定。',verification:'爭點核查',verificationNote:'針對重要分歧補查公開來源',notReported:'未記錄',actualModel:'回報的主回答模型',requestedModel:'要求使用的模型',requestedEffort:'要求的推理強度',defaultEffort:'官方預設（未另指定）',effortNote:'這是送出的設定；不代表實際 Thinking 內容、token 數或完成品質。',snapshotNote:'沿用這場會議保存的模型設定',previewNote:'新會議使用目前設定；模型品質不因研究深度降低',calls:'次主要模型呼叫',quotaNote:'會使用訂閱額度；此處無法取得可靠的剩餘額度或完成時間。',source_check:'公開來源核對',sourceCheck:'核對公開來源',checkingSource:'正在核對…',sourceCheckNote:'只擷取公開來源／書目資訊，不呼叫模型。擷取與引文比對不能證實研究主張。',sourceReported:'模型／匯入內容所報資料',sourceObserved:'本機來源核對結果',reportedAccess:'回答聲稱的讀取範圍',observedAccess:'實際取得範圍',published:'發表日期',studyType:'研究類型',population:'適用／研究對象',quote:'提供的引文',locator:'段落／頁碼',quoteMatch:'引文文字比對',checked:'來源已擷取',partial:'取得部分資料',unavailable:'未取得資料',blocked:'來源未允許讀取',unchecked:'尚未核對',metadata:'書目資訊',abstract:'摘要',webpage:'網頁文字',noClaimProof:'以上不代表主張已證實，也不代表已讀完整論文。',claimsTitle:'討論中的研究主張',claimNote:'主張、證據類型及信心由模型提出；請搭配原始來源判斷。',confidence:'模型自述信心',evidenceType:'模型分類的證據類型',recommendation:'條件式建議',optionComparison:'選項比較',benefits:'可能好處',tradeoffs:'代價與風險',conditions:'成立條件',nextSteps:'可採取的下一步',uncertainties:'尚未釐清',changes:'相較原版的變化（模型自述）',emptySummary:'從你的問題與決策背景開始',summaryPending:'尚無整合摘要。已完成的發言可在「完整討論」查看。',legacySummary:'此紀錄沒有結構化摘要，以下顯示已保存的整合原文。',modelSummaryNote:'以下是模型整理的決策建議，須結合來源核對與適用條件。',followup:'追問／更新證據',followupHint:'保留原會議，帶入其討論背景建立新版。建立後先檢視，再按開始研究。',followupQuestion:'這次想進一步問什麼？',followupEvidence:'新增研究、來源或情況',createRevision:'建立新版，先不執行',revisionReady:'新版已建立，尚未呼叫模型。請檢視設定後開始研究。',parentVersion:'查看原版',revision:'版本',savedInputs:'這是已保存的問題與設定；要調整請建立新版或新研究。',whyItMatters:'為何影響決策',whatToCheck:'需要補查什麼',positions:'不同觀點',reportedStatus:'模型標記的狀態',noDisputes:'尚無結構化分歧紀錄',noDisputesNote:'這不代表模型已達成共識；可查看完整討論與摘要中的不確定性。',warnings:'資料處理提示',started:'這次執行開始',elapsed:'本次執行已過時間',stepsComplete:'模型步驟已完成',planned:'已安排',legacyPlan:'舊版會議沿用原流程',examplePacket:'科技展望案例資料（可選）',sourceMissing:'尚無可列出的來源；沒有引用不等於已驗證。',savedSourceNote:'來源擷取結果有各自的查閱時間，不保證持續更新。',start:'開始研究',startQueued:'開始這個版本',showOriginal:'查看模型原始資料區塊',finalSource:'相關來源',modelRecord:'模型與執行紀錄',viewDiscussion:'查看完整討論',followupRequiresQuestion:'請填寫這次的追問。',checkFinished:'来源核對已更新。',draftMissing:'尚未補充',noAutomaticRun:'這一步只建立新版，不呼叫模型。',effort:'要求的推理強度'});
