Object.assign(copy.zh,{research:'研究證據',inference:'推論',scenario:'情境',full_text:'全文（回答自述）',not_read:'尚未讀取',openDispute:'尚待釐清',partly_resolved:'部分釐清',resolved:'已釐清（模型自述）'});
Object.assign(copy.en,{research:'Research evidence',inference:'Inference',scenario:'Scenario',full_text:'Full text (response-reported)',not_read:'Not read',openDispute:'Open',partly_resolved:'Partly resolved',resolved:'Resolved (model-reported)'});
function decisionFields(value,prefix='decision',locked=false){return `<div class="decision-grid">${decisionKeys.map(k=>`<label class="field-label" for="${prefix}-${k}">${t(k)}<textarea id="${prefix}-${k}" class="decision-input" placeholder="${esc(t(k+'Hint'))}" ${locked?'readonly':''}>${esc(value?.[k]||'')}</textarea></label>`).join('')}</div>`}
function depthChoices(value,id='depth',locked=false){return `<label class="field-inline" for="${id}">${t('depth')}<select id="${id}" ${locked?'disabled':''}>${['overview','standard','deep'].map(d=>`<option value="${d}" ${value===d?'selected':''}>${t(d)}</option>`).join('')}</select></label>`}
function callRange(){const s=state.session,n=s?.participants?.length||state.selected.size,depth=s?.depth||state.depth;if(s?.plan)return {min:s.plan.total,max:s.plan.maxCalls};if(!n)return {min:0,max:0};if(n===1)return {min:s&&(s.protocolVersion||1)<3?1:2,max:s&&(s.protocolVersion||1)<3?1:2};const base=depth==='overview'?n+1:2*n+1;return {min:base,max:base+(depth==='deep'?2:depth==='standard'?1:0)}}
function previewView(){const r=callRange(),models=(state.session?.participants||[...state.selected]).map(id=>{const p=state.providers.find(p=>p.id===id)||{id,name:id};const snap=state.session?.modelSnapshot?.[id];return `<li><strong>${esc(p.name)}</strong> · ${esc(snap?.model||(!snap?p.model:'')||t('defaultModel'))} · ${esc((snap?snap.reasoningEffort:p.reasoningEffort)||t('defaultEffort'))}</li>`}).join('');const missing=decisionKeys.filter(k=>!state.decision[k]?.trim());return `<div class="run-preview"><div class="preview-heading"><strong>${t(state.session?.depth||state.depth)}</strong><span class="pill">${r.min===r.max?r.min:`${r.min}–${r.max}`} ${t('calls')}</span></div><ul class="model-preview">${models}</ul><p class="footnote">${state.session&&Object.keys(state.session.modelSnapshot||{}).length?t('snapshotNote'):t('previewNote')}</p><p class="footnote">${t('quotaNote')}</p>${!state.session||state.session.protocolVersion>=2?`<p class="footnote">${sourceBudgetNote()}</p>`:''}<p class="footnote">${t('privacy')}</p>${missing.length?`<p class="footnote">${t('draftMissing')}：${missing.map(t).join(' · ')}</p>`:''}</div>`}
function lab(){const s=state.session,locked=!!s,canStart=!s||s.status==='queued',canResume=s&&['paused','failed'].includes(s.status);return `<div class="title-row"><div><h1>${t('title')}</h1><div class="subtle">${t('subtitle')}</div></div><button class="btn" data-action="new">${icon('plus')}${t('new')}</button></div><div class="content-grid"><div class="column"><section class="panel"><div class="panel-body">${s?.parentSessionId?`<div class="revision-banner"><span class="pill">${t('revision')} ${esc(s.revision||2)}</span><button class="text-link" data-session="${esc(s.parentSessionId)}">${t('parentVersion')} ↗</button></div>`:''}<div class="composer-top"><label for="question" class="field-label">${t('question')}</label>${!locked?`<button class="text-link" data-action="example">${t('example')}</button>`:''}</div><textarea id="question" class="question" ${locked?'readonly':''}>${esc(state.question)}</textarea><div class="composer-options"><label class="field-inline">${t('topic')}<select id="topic" ${locked?'disabled':''}>${['technology','academic','health','general'].map(v=>`<option value="${v}" ${state.topic===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><label class="field-inline">${t('answer')}<select id="answer-lang" ${locked?'disabled':''}>${['zh','en','auto'].map(v=>`<option value="${v}" ${state.answerLang===v?'selected':''}>${t(v)}</option>`).join('')}</select></label>${depthChoices(state.depth,'depth',locked)}</div><details class="decision-context" ${!locked?'open':''}><summary>${t('decisionContext')}</summary><p class="footnote">${t('optionalContext')}</p>${decisionFields(state.decision,'decision',locked)}</details><details><summary>${t('evidenceLabel')}</summary><textarea id="evidence" class="standard" placeholder="${t('evidencePlaceholder')}" ${locked?'readonly':''}>${esc(state.evidence)}</textarea>${!locked?`<div class="manual-tools"><button class="btn small" data-action="attach">${icon('file',15)}${t('attach')}</button><span class="footnote">${t('attachHint')}</span></div><input type="file" id="file-input" class="file-input" accept=".txt,.md,.json" multiple>`:''}<div class="attachment-list">${state.attachments.map((a,i)=>`<span class="attachment">${icon('file',13)}${esc(a.name)}${!locked?`<button data-remove-attachment="${i}" aria-label="${t('delete')}">×</button>`:''}</span>`).join('')}</div>${state.useBrief?`<label class="field-inline"><input type="checkbox" id="use-brief" checked ${locked?'disabled':''}>${t('briefUse')}</label><p class="footnote">${t('briefUseHint')}</p>`:''}</details>${locked?`<p class="footnote saved-inputs">${t('savedInputs')}</p>`:''}${canStart?previewView():''}${!s?clarificationView():''}<div class="composer-footer"><div class="participants">${state.providers.map(p=>`<label class="participant ${!p.ready?'disabled':''}"><input type="checkbox" data-provider="${esc(p.id)}" ${state.selected.has(p.id)?'checked':''} ${!p.ready||locked?'disabled':''}>${symbol(p.id)}${esc(p.name)}</label>`).join('')}</div>${state.running?`<button class="btn danger" data-action="cancel"><span class="running-icon"></span>${t('cancel')}</button>`:canResume?`<button class="btn primary" data-action="resume" ${state.starting?'disabled':''}>${t('resume')}</button>`:canStart?`<button class="btn primary" data-action="start" ${state.starting||state.clarifying||state.evalBusy||state.evaluation?.status==='running'||!state.selected.size?'disabled':''}>${icon('arrow')}${t(s?'startQueued':state.selected.size===1?'single':'start')}</button>`:`<button class="btn primary" data-action="followup">${t('followup')}</button>`}</div>${canResume?`<div class="notice amber">${t('errorLabel')}</div>`:''}${s?.status==='queued'&&s.parentSessionId?`<div class="notice">${t('revisionReady')}</div>`:''}</div></section>${runProgress()}<div class="section-nav" role="tablist">${['summary','evidence','disputes','discussion'].map(tab=>`<button role="tab" aria-selected="${state.tab===tab}" data-tab="${tab}" class="${state.tab===tab?'active':''}">${t(tab)}</button>`).join('')}</div><div id="tab-content">${state.tab==='summary'?summaryView():state.tab==='evidence'?sourcesView():state.tab==='disputes'?disputesView():discussionView()}</div>${followupView()}</div>${rail()}</div>`}
function rail(){const s=state.session;return `<aside class="rail"><section class="panel"><div class="panel-head"><h2>${t('modelRecord')}</h2></div><div class="panel-body"><p class="footnote">${s&&Object.keys(s.modelSnapshot||{}).length?t('snapshotNote'):t('previewNote')}</p>${(s?.participants||[...state.selected]).map(id=>{const p=state.providers.find(x=>x.id===id)||{name:id},snap=s?.modelSnapshot?.[id],messages=list(s?.messages).filter(m=>m.provider===id&&!m.stale),reported=[...new Set(messages.map(m=>m.model).filter(Boolean))];return `<div class="model-record"><strong>${esc(p.name)}</strong><dl><dt>${t('requestedModel')}</dt><dd>${esc((snap?snap.model:p.model)||t('defaultModel'))}</dd><dt>${t('requestedEffort')}</dt><dd>${esc((snap?snap.reasoningEffort:p.reasoningEffort)||t('defaultEffort'))}</dd><dt>${t('actualModel')}</dt><dd>${esc(reported.join(', ')||t('notReported'))}</dd></dl></div>`}).join('')}<p class="footnote">${t('effortNote')}</p><button class="text-link" data-page="settings">${t('setup')} →</button></div></section><section class="panel"><div class="panel-head"><h2>${t('principle')}</h2></div><div class="panel-body"><p class="subtle">${t('principleText')}</p><p class="footnote">${t('noExtra')}</p></div></section></aside>`}
function runProgress(){const s=state.session;if(!s)return '';const plan=s.plan,started=s.runStartedAt||s.startedAt,percent=plan?.total?Math.min(s.status==='running'?95:100,100*plan.completed/plan.total):null;return `<section class="panel run-status" aria-live="polite"><div class="panel-body"><div class="preview-heading"><strong>${t(s.status)}${s.currentStage?` · ${t(s.currentStage)} · ${esc(s.currentProvider||'')}`:''}</strong>${plan?`<span>${plan.completed} / ${plan.total} ${t('stepsComplete')}</span>`:''}</div>${percent!==null?`<div class="progress-bar"><span style="width:${percent}%"></span></div>`:''}<div class="run-times"><span>${t('started')}：${dateLabel(started)}</span>${started?`<span>${t('elapsed')}：<b data-elapsed="${esc(started)}">${elapsedLabel(started,s.status)}</b></span>`:''}</div>${plan?`<ol class="step-list">${list(plan.steps).map((step,i)=>`<li class="${(step.complete??i<plan.completed)?'done':s.currentStage===step.stage&&(s.currentProvider===step.provider||s.currentProvider===state.providers.find(p=>p.id===step.provider)?.name)?'active':''}"><span>${(step.complete??i<plan.completed)?'✓':i+1}</span>${esc(t(step.stage))} · ${esc(state.providers.find(p=>p.id===step.provider)?.name||step.provider)}</li>`).join('')}</ol><p class="footnote">${t('planned')} ${plan.total} · ${bi('最多','Up to')} ${plan.maxCalls} ${t('calls')}${plan.pendingChecks?` · ${bi('待查爭點','Pending checks')} ${Array.isArray(plan.pendingChecks)?plan.pendingChecks.length:esc(plain(plan.pendingChecks))}`:''}</p>`:`<p class="footnote">${t('legacyPlan')}</p>`}${s.error||s.errorIssue?issueView(s.errorIssue,s.error):''}</div></section>`}
function elapsedLabel(start,status){if(status!=='running'&&!state.session?.runFinishedAt&&!state.session?.completedAt)return t('notReported');const end=status==='running'?Date.now():Date.parse(state.session?.runFinishedAt||state.session?.completedAt),seconds=Math.max(0,Math.floor((end-Date.parse(start))/1000));return Number.isFinite(seconds)?`${Math.floor(seconds/60)}m ${seconds%60}s`:t('notReported')}
function summaryView(){const s=state.session,a=analysis(),summary=a.summary,final=lastSynthesis(),has=summary&&(summary.recommendation||list(summary.options).length||list(summary.nextSteps).length);return `${s?.messages?.length?`<div class="section-title"><span class="subtle">${t('report')}</span><button class="btn small" data-action="export">${icon('download',14)}${t('export')}</button></div>`:''}${evidenceReviewView()}${has?`<section class="panel summary-card"><div class="panel-body"><span class="eyebrow">${t('recommendation')}</span><div class="message-body recommendation">${markdown(plain(summary.recommendation))}</div><p class="footnote">${t('modelSummaryNote')}</p>${list(summary.options).length?`<h3>${t('optionComparison')}</h3><div class="option-grid">${summary.options.map(o=>`<article class="option-card"><h3>${esc(plain(o.name))}</h3><dl>${['benefits','tradeoffs','conditions'].map(k=>`<dt>${t(k)}</dt><dd>${esc(plain(o[k])||t('notReported'))}</dd>`).join('')}</dl></article>`).join('')}</div>`:''}${['nextSteps','uncertainties','changes'].filter(k=>list(summary[k]).length).map(k=>`<div class="summary-section"><h3>${t(k)}</h3><ul>${textList(summary[k])}</ul></div>`).join('')}</div></section>`:final?`<section class="panel"><div class="panel-body"><p class="notice">${t('legacySummary')}</p><div class="message-body">${markdown(responseText(final.text))}</div></div></section>`:`<section class="panel empty"><h3>${s?t('summaryPending'):t('emptySummary')}</h3><p>${t('optionalContext')}</p>${s?.messages?.length?`<button class="btn" data-tab="discussion">${t('viewDiscussion')}</button>`:''}</section>`}${list(a.warnings).length?`<div class="notice amber"><strong>${t('warnings')}</strong><ul>${textList(a.warnings)}</ul></div>`:''}${state.useBrief?`<details class="example-details"><summary>${t('examplePacket')} · ${t('notDebate')}</summary>${briefView()}</details>`:''}`}
function sourceBudgetNote(){
  const cap={overview:1,standard:3,deep:5}[state.session?.depth||state.depth]||3;
  if(state.session&&(state.session.protocolVersion||1)<3)return bi(`完成後核對最多 ${cap} 份公開來源，不增加模型呼叫。`,`Checks up to ${cap} public sources after the answer, without additional model calls.`);
  return bi(`整合前最多核對 ${cap} 次來源引用；完成後再核對最多 ${cap} 次新增或變更的引用，不增加模型呼叫。同份來源的不同引文分別核對。`,`Checks up to ${cap} source citations before synthesis and up to ${cap} new or changed citations afterward, without additional model calls. Different quotations from one source are checked separately.`);
}
function synthesisChair(){return [state.session?.chair,...state.selected,...state.providers.filter(p=>p.defaultSelected!==false).map(p=>p.id)].find(id=>state.providers.some(p=>p.id===id&&p.ready))}
function evidenceReviewView(){
  const a=analysis(),review=a.evidenceReview;
  if(!review||!lastSynthesis())return '';
  const changed=review.status==='changed_after_synthesis',incorporated=review.status==='incorporated';
  const title=changed?bi('來源核對已有更新，摘要尚未重新評估','Source checks changed; synthesis has not been reassessed'):incorporated?bi('來源核對結果已提供給整合模型','Source checks were supplied to the synthesis model'):bi('這份整合未記錄來源核對輸入','No source-check input was recorded for this synthesis');
  const note=changed?bi('以下仍是原本的建議。你可以依目前核對結果重新整合，或以追問建立新版本。','The original recommendation remains below. Reassess it with current checks, or create a follow-up version.'):incorporated?bi('這表示模型取得了核對資料，不代表它的解讀或主張已被證實。','This records that checks were supplied, not that the model’s interpretation or claims were established.'):bi('目前顯示的核對資料，不應視為模型當時已考慮的證據。','The checks visible now should not be assumed to have informed the original answer.');
  const chair=synthesisChair(),provider=state.providers.find(p=>p.id===chair),snap=state.session?.modelSnapshot?.[chair];
  const actionAvailable=!state.running&&!state.starting&&(changed||!incorporated||review.uncheckedFinalCount>0||review.unreviewedFinalCount>0);
  const canReassess=state.session?.protocolVersion>=3;
  return `<section class="evidence-review ${changed?'changed':''}" aria-label="${bi('整合採用的核對資料','Source checks used in synthesis')}"><strong>${title}</strong><p>${note}</p><div class="review-counts">${Number.isFinite(review.checkedCount)?`<span>${bi('整合時帶入的核對紀錄','Checks supplied to synthesis')}：${review.checkedCount}</span>`:''}${Number.isFinite(review.remainingCount)&&review.remainingCount>0?`<span>${bi('尚未核對的引用','Citations not checked')}：${review.remainingCount}</span>`:''}${Number.isFinite(review.newCheckCount)&&review.newCheckCount>0?`<span>${bi('整合後新增或變更的核對','New or changed checks after synthesis')}：${review.newCheckCount}</span>`:''}${Number.isFinite(review.unreviewedFinalCount)&&review.unreviewedFinalCount>0?`<span>${bi('尚未帶入整合的最終引用','Final citations not yet reviewed in synthesis')}：${review.unreviewedFinalCount}</span>`:''}${Number.isFinite(review.uncheckedFinalCount)&&review.uncheckedFinalCount>0?`<span>${bi('最終回答尚有未核對引用','Unchecked citations in the final answer')}：${review.uncheckedFinalCount}</span>`:''}</div>${actionAvailable?`<div class="manual-tools">${canReassess?`<button class="btn small" data-action="review-synthesis" ${!chair?'disabled':''}>${bi('依核對結果重新整合','Reassess using source checks')}</button>`:''}<button class="text-link" data-action="followup">${t('followup')}</button></div>`:''}${state.reviewSynthesis&&actionAvailable&&canReassess?`<div class="resynthesis-preview" id="review-synthesis-preview"><strong>${bi('重新整合預覽','Reassessment preview')}</strong><p>${esc(provider?.name||chair||t('notReported'))} · ${esc((snap?snap.model:provider?.model)||t('defaultModel'))} · ${esc((snap?snap.reasoningEffort:provider?.reasoningEffort)||t('defaultEffort'))}</p><p>${bi('1 次主要模型呼叫，會使用訂閱額度。保留舊整合原文，將目前核對結果提供給主持模型重新評估。','1 main model call, using subscription quota. Keeps the previous synthesis and supplies current checks to the chair for reassessment.')}</p><button class="btn primary small" data-action="synthesize" ${!chair?'disabled':''}>${bi('開始重新整合','Start reassessment')}</button></div>`:''}</section>`;
}
function evidenceGroups(a=analysis()){
  return list(a.sourceGroups).length?a.sourceGroups:list(a.sources).map(s=>({id:s.id,title:s.title,url:s.url,doi:s.doi,occurrences:[s],citationCount:1,providers:[s.providerName||s.provider].filter(Boolean)}));
}
function sourceChips(ids,a=analysis()){
  const groups=evidenceGroups(a),seen=new Set();
  return `<div class="source-chips">${list(ids).map(id=>{const groupId=a.sourceGroupByOccurrence?.[id]||id;if(seen.has(groupId))return '';seen.add(groupId);const group=groups.find(g=>g.id===groupId),source=list(a.sources).find(x=>x.id===id);return `<a href="#source-${esc(groupId)}" data-source-target="${esc(groupId)}">${esc(group?.title||source?.title||group?.doi||group?.url||id)}</a>`}).join('')}</div>`;
}
function sourcesView(){
  const a=analysis(),groups=evidenceGroups(a),sources=list(a.sources),citations=sources.length?[]:sessionCitations();
  return `<p class="subtle">${t('sourceCheckNote')}</p><p class="footnote">${t('savedSourceNote')}</p>${groups.length?`<div class="evidence-counts"><strong>${groups.length} ${bi('份不同來源','unique sources')}</strong><span>${sources.length} ${bi('次引用','citations')}</span></div><p class="footnote">${bi('相同來源合併展示，各次引文與核對結果保留。不同來源數不等於獨立研究數或證據強度。','Repeated sources are grouped while each quotation and check is preserved. Unique-source counts are not counts of independent studies or measures of evidence strength.')}</p>`:''}${list(a.claims).length?`<section class="panel"><div class="panel-body"><h2>${t('claimsTitle')}</h2><p class="footnote">${t('claimNote')}</p>${a.claims.map(c=>`<article class="claim-card"><p>${esc(plain(c.statement))}</p><div class="claim-meta">${c.evidenceType?`<span>${t('evidenceType')}：${esc(t(plain(c.evidenceType)))}</span>`:''}${c.confidence?`<span>${t('confidence')}：${esc(plain(c.confidence))}</span>`:''}</div>${c.limitations?`<p class="footnote">${t('limitations')}：${esc(plain(c.limitations))}</p>`:''}${sourceChips(c.sourceIds,a)}</article>`).join('')}</div></section>`:''}${groups.length?groups.map(sourceGroupView).join(''):citations.length?citations.map(s=>`<article class="source-card"><span class="pill amber">${t('unchecked')}</span><h3><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p class="footnote">${esc([...s.providers].join(' · '))} · ${t('sourceReported')}</p><small>${esc(s.url)}</small></article>`).join(''):`<section class="panel empty">${t('sourceMissing')}</section>`}${state.useBrief?`<details class="example-details"><summary>${t('examplePacket')}</summary><p class="footnote">${t('sourceNote')}</p>${list(state.brief?.sources).map(s=>`<article class="source-card"><span class="pill">${esc(s.id)} · ${esc(sourceType(s.type))}</span><h3><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(val(s,'summary'))}</p><small>${t('limitations')}：${esc(val(s,'limitation'))}</small></article>`).join('')}</details>`:''}`;
}
function sourceGroupView(group){
  const occurrences=list(group.occurrences),url=safeUrl(group.url||''),checked=occurrences.filter(s=>s.check).length;
  const providers=[...new Set(occurrences.map(s=>s.providerName||state.providers.find(p=>p.id===s.provider)?.name||s.provider).filter(Boolean))];
  return `<article class="source-card source-group" id="source-${esc(group.id)}"><div class="preview-heading"><span class="pill">${occurrences.length} ${bi('次引用','citations')} · ${providers.length} ${t('providerCount')}</span><span class="footnote">${checked} / ${occurrences.length} ${bi('次已嘗試核對','checks attempted')}</span></div><h3>${url!=='#'?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(group.title||group.doi||group.url)} ↗</a>`:esc(group.title||group.doi||t('notReported'))}</h3>${group.doi?`<p class="footnote">DOI：${esc(group.doi)}</p>`:''}<p class="footnote">${esc(providers.join(' · '))}</p><div class="source-occurrences">${occurrences.map(sourceView).join('')}</div></article>`;
}
function sourceView(s){
  const c=s.check,busy=state.checkingSources.has(s.id),provider=s.providerName||state.providers.find(p=>p.id===s.provider)?.name||s.provider||t('notReported');
  const quoteStatus=!s.quote?'':c?.quoteMatch===true?bi('引文文字相符','Quote text matches'):c?.quoteMatch===false?bi('取得內容未找到引文','Quote not found in retrieved text'):bi('引文尚未比對','Quote not compared');
  return `<details class="citation-detail" data-citation-detail="${esc(s.id)}" ${state.expandedCitations.has(s.id)?'open':''}><summary><span class="citation-identity"><strong>${esc(provider)}</strong> · ${esc(t(s.stage||'independent'))}</span><span class="citation-badges"><span class="pill ${!c||['blocked','unavailable'].includes(c.status)?'amber':'blue'}">${esc(t(c?.status||'unchecked'))}</span>${quoteStatus?`<span class="footnote">${quoteStatus}</span>`:''}</span></summary><p class="footnote">${dateLabel(s.createdAt)}${s.manual?` · ${t('manualLabel')}`:''}</p><div class="source-reported"><strong class="footnote">${t('sourceReported')}</strong><dl>${[['published',s.publishedAt],['studyType',s.studyType],['population',s.population],['reportedAccess',s.reportedAccess],['locator',s.locator],['DOI',s.doi]].filter(([,v])=>v).map(([k,v])=>`<dt>${t(k)}</dt><dd>${esc(k==='reportedAccess'?t(plain(v)):plain(v))}</dd>`).join('')}</dl>${s.quote?`<blockquote><strong>${t('quote')}</strong><br>${esc(plain(s.quote))}</blockquote>`:''}</div>${c?`<div class="source-observed"><strong>${t('sourceObserved')}</strong><p class="footnote">${dateLabel(c.checkedAt)} · ${t('observedAccess')}：${esc(t(c.access||'unavailable'))}</p>${s.checkReusedFrom?`<p class="footnote">${bi('沿用相同來源與引文的核對，查閱時間如上。','Reuses the check for the same source and quotation, at the access time shown above.')}</p>`:''}${c.metadata?`<dl>${[['Title',c.metadata.title],['DOI',c.metadata.doi],['published',c.metadata.publishedAt],['studyType',c.metadata.type]].filter(([,v])=>v).map(([k,v])=>`<dt>${k==='Title'?bi('擷取到的標題','Retrieved title'):t(k)}</dt><dd>${esc(plain(v))}</dd>`).join('')}</dl>`:''}<p class="footnote">${t('quoteMatch')}：${c.quoteMatch===true?bi('找到相符文字','Matching text found'):c.quoteMatch===false?bi('在取得的內容中未找到；不代表引文必然錯誤','Not found in retrieved content; this does not establish that the quote is wrong'):bi('未比對／資料不足','Not compared / insufficient content')}</p>${c.note?`<p>${esc(plain(c.note))}</p>`:''}${c.retrievedUrl?`<a class="text-link" href="${esc(safeUrl(c.retrievedUrl))}" target="_blank" rel="noopener noreferrer">${bi('開啟實際取得的來源','Open retrieved source')} ↗</a>`:''}<p class="footnote">${t('noClaimProof')}</p></div>`:''}<button class="btn small" data-check-source="${esc(s.id)}" ${busy||state.running||state.starting?'disabled':''}>${busy?t('checkingSource'):t('sourceCheck')}</button></details>`;
}
function issueStatus(status){return t(status==='open'?'openDispute':status||'openDispute')}
function disputeObservationView(d,isLatest=false){
  const provider=d.providerName||state.providers.find(p=>p.id===d.provider)?.name||d.provider||t('notReported');
  const isCurrent=isLatest&&!d.stale,sourceIds=list(d.sourceIds),visibleIds=sourceIds.filter(id=>list(analysis().sources).some(s=>s.id===id));
  return `<li class="issue-observation ${isCurrent?'latest':''} ${d.stale?'superseded':''}"><div class="issue-event-heading"><strong>${esc(provider)} · ${esc(t(d.stage||'critique'))}</strong><span class="pill ${d.stale?'':d.status==='resolved'?'blue':'amber'}">${d.stale?`${t('stale')} · `:''}${esc(issueStatus(d.status))}</span></div><p class="footnote">${dateLabel(d.createdAt)}${isCurrent?` · ${bi('最近一次模型評估','Latest model assessment')}`:''}</p>${[['positions',d.positions],['whyItMatters',d.whyItMatters],['whatToCheck',d.whatToCheck],['reason',d.reason]].filter(([,v])=>v).map(([k,v])=>`<div class="dispute-detail"><strong>${k==='reason'?bi('評估依據與改變原因','Assessment basis and reason for change'):t(k)}</strong><p>${esc(plain(v))}</p></div>`).join('')}${visibleIds.length?`<strong class="footnote">${t('finalSource')}</strong>${sourceChips(visibleIds)}`:''}${sourceIds.length>visibleIds.length?`<p class="footnote">${bi('先前引用保留在原始發言中。','Earlier citations are preserved in the original response.')} <button class="text-link" data-tab="discussion">${t('viewDiscussion')}</button></p>`:''}</li>`;
}
function issueThreadView(thread){
  const history=list(thread.history),superseded=thread.superseded===true||history.length>0&&history.every(d=>d.stale),latest=superseded?null:thread.latest||history.findLast(d=>!d.stale)||thread,status=latest?(thread.status||latest.status):null;
  const changed=thread.statusChanged||new Set(history.map(h=>h.status)).size>1,conflicting=!superseded&&thread.hasConflictingAssessments;
  const statusLabel=superseded?bi('先前版本的爭點','Issue from an earlier version'):conflicting?bi('模型評估仍有分歧','Model assessments still differ'):issueStatus(status);
  return `<article class="panel issue-thread ${superseded?'superseded':''}" id="issue-${esc(thread.id)}"><div class="panel-body"><div class="preview-heading"><span class="eyebrow">${bi('爭點歷程','Issue history')}</span><span class="pill ${superseded?'':!conflicting&&status==='resolved'?'blue':'amber'}">${esc(statusLabel)}</span></div><h3>${esc(plain(thread.question||latest?.question||history[0]?.question))}</h3><p class="footnote">${superseded?bi('此爭點只有先前版本的評估；保留歷程，不代表目前的結論或狀態。','This issue has assessments only from earlier versions. Its history is preserved without assigning a current conclusion or status.'):bi('以上為目前保留的模型評估，不代表爭點已客觀解決。各輪觀點與先前不同判斷保留如下。','The status reflects current model assessments, not proof that the issue is settled. Earlier positions and differing judgments remain below.')}</p>${conflicting?`<p class="issue-change-note">${bi('各模型最近的評估仍有不同，請查看下方觀點。','The models’ latest assessments still differ. Compare their positions below.')}</p>`:''}${changed?`<p class="issue-change-note">${bi('狀態曾改變：請一併查看前後依據。','The assessment changed. Compare the evidence and reasoning across stages.')}</p>`:''}<ol class="issue-timeline">${history.length?history.map(d=>disputeObservationView(d,!!latest&&(d===latest||!!d.id&&d.id===latest.id))).join(''):latest?disputeObservationView(latest,true):''}</ol></div></article>`;
}
function disputesView(){
  const a=analysis(),items=list(a.issueThreads).length?a.issueThreads:list(a.disputes).map(d=>({...d,history:[d],latest:d})),uncertainties=list(a.summary?.uncertainties);
  return `${items.length?items.map(issueThreadView).join(''):`<section class="panel empty"><h3>${t('noDisputes')}</h3><p>${t('noDisputesNote')}</p><button class="btn" data-tab="discussion">${t('viewDiscussion')}</button></section>`}${uncertainties.length?`<section class="panel"><div class="panel-body"><h3>${t('uncertainties')}</h3><ul>${textList(uncertainties)}</ul></div></section>`:''}`;
}
function bindResearchDetails(){
  document.querySelectorAll('[data-citation-detail]').forEach(el=>el.ontoggle=()=>el.open?state.expandedCitations.add(el.dataset.citationDetail):state.expandedCitations.delete(el.dataset.citationDetail));
  document.querySelectorAll('[data-source-target]').forEach(el=>el.onclick=e=>{e.preventDefault();capture();state.tab='evidence';render();document.getElementById('source-'+el.dataset.sourceTarget)?.scrollIntoView({behavior:'smooth',block:'start'})});
}
function followupView(){const s=state.session;if(!s||state.running||!s.messages?.length)return '';const f=state.followup;if(!f)return `<button class="btn" data-action="followup">${icon('plus')}${t('followup')}</button>`;return `<section class="panel" id="followup-panel"><div class="panel-head"><h2>${t('followup')}</h2><button class="text-link" data-action="followup-close">×</button></div><div class="panel-body"><p class="subtle">${t('followupHint')}</p><label class="field-label" for="followup-question">${t('followupQuestion')}</label><textarea id="followup-question" class="standard">${esc(f.question)}</textarea><label class="field-label" for="followup-evidence">${t('followupEvidence')}</label><textarea id="followup-evidence" class="standard">${esc(f.evidence)}</textarea><details><summary>${t('decisionContext')}</summary>${decisionFields(f.decision,'followup')}</details><div class="composer-options">${depthChoices(f.depth,'followup-depth')}</div><div class="participants">${state.providers.map(p=>`<label class="participant ${!p.ready?'disabled':''}"><input type="checkbox" data-followup-provider="${esc(p.id)}" ${f.participants.includes(p.id)?'checked':''} ${!p.ready||state.starting?'disabled':''}>${symbol(p.id)}${esc(p.name)}</label>`).join('')}</div><p class="footnote">${t('noAutomaticRun')}</p><button class="btn primary" data-action="create-followup" ${state.starting?'disabled':''}>${t('createRevision')}</button></div></section>`}


function adoptSession(session,resetTab=true){state.clarification=null;state.session=session;state.question=session.question||'';state.topic=session.topic||'general';state.answerLang=session.answerLang||'zh';state.useBrief=session.useBrief===true;state.evidence=session.evidence||'';state.attachments=list(session.attachments);state.depth=session.depth||'standard';state.decision={...emptyDecision(),...session.decision};state.selected=new Set(session.participants||[]);state.running=session.status==='running';state.page='lab';if(resetTab)state.tab='summary';state.followup=null;state.reviewSynthesis=false;state.expandedCitations.clear();state.showManual=false;state.manualDraft=null;localStorage.setItem('rt-last-session',session.id)}
function updateElapsed(){document.querySelectorAll('[data-elapsed]').forEach(el=>{el.textContent=elapsedLabel(el.dataset.elapsed,state.session?.status)})}
setInterval(updateElapsed,1000);


